package com.inventra.backend.service; import com.inventra.backend.dto.*; import com.inventra.backend.model.*; import com.inventra.backend.repository.*; import org.springframework.stereotype.Service; import java.util.*; @Service public class AnomalyDetectionService {private final ProductRepository products;private final InventoryTransactionRepository tx;public AnomalyDetectionService(ProductRepository p,InventoryTransactionRepository t){products=p;tx=t;}public List<AnomalyResponse> detect(){List<AnomalyResponse> out=new ArrayList<>();for(Product p:products.findAll()){List<InventoryTransaction> sales=tx.findByProductIdAndType(p.getId(),InventoryTransactionType.SALE);if(sales.size()<5)continue;double avg=sales.stream().mapToInt(InventoryTransaction::getQuantity).average().orElse(0);double var=sales.stream().mapToDouble(x->Math.pow(x.getQuantity()-avg,2)).average().orElse(0);double sd=Math.sqrt(var);double recent=sales.get(sales.size()-1).getQuantity();double z=sd==0?0:Math.abs(recent-avg)/sd;if(z>=2){out.add(new AnomalyResponse(p.getId(),p.getSku(),p.getName(),true,avg,recent,z,"Recent sales movement is unusually different from the historical pattern."));}}return out;}}
